import{_ as r,o as a,c as o,a2 as d}from"./chunks/framework.F7eQ-ohH.js";const g=JSON.parse('{"title":"写项目经历的STAR和三段式法则","description":"","frontmatter":{},"headers":[],"relativePath":"docs/项目润色/写项目经历的STAR和三段式法则.md","filePath":"docs/项目润色/写项目经历的STAR和三段式法则.md","lastUpdated":1788881428000}'),e={name:"docs/项目润色/写项目经历的STAR和三段式法则.md"};function l(p,t,n,s,i,h){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="写项目经历的star和三段式法则" tabindex="-1">写项目经历的STAR和三段式法则 <a class="header-anchor" href="#写项目经历的star和三段式法则" aria-label="Permalink to &quot;写项目经历的STAR和三段式法则&quot;">​</a></h1><p>简历里的项目经历，是除了教育背景和实习经历之外<strong>最重要的部分</strong>。</p><p>面试官看简历的顺序大致是这样的：学历 → 实习单位 → 项目经历。项目经历往往是他们花时间最多、问得最深的一块。</p><p>写好项目经历是有方法的。这里分享两种：<strong>STAR 法则</strong>和<strong>三段式法则</strong>。</p><hr><h1 id="star-法则" tabindex="-1">STAR 法则 <a class="header-anchor" href="#star-法则" aria-label="Permalink to &quot;STAR 法则&quot;">​</a></h1><p>STAR 是一种叙述经历的结构框架，无论技术类还是非技术类项目都适用。</p><table tabindex="0"><thead><tr><th>字母</th><th>含义</th><th>说明</th></tr></thead><tbody><tr><td>S</td><td>Situation（情境）</td><td>描述项目背景、时间、环境</td></tr><tr><td>T</td><td>Task（任务）</td><td>你在这个项目中具体承担什么任务</td></tr><tr><td>A</td><td>Action（行动）</td><td>你为完成任务采取了哪些具体步骤</td></tr><tr><td>R</td><td>Result（结果）</td><td>最终成果，尽量量化</td></tr></tbody></table><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><blockquote><p><strong>情境（S）</strong>：在 xxxx 年，我作为 Java 开发团队成员，参与了公司订单管理系统的重构项目，目标是提升系统性能和可扩展性。</p><p><strong>任务（T）</strong>：负责设计和实现新的 RESTful API 接口，处理复杂订单查询逻辑，并与前端无缝集成。</p><p><strong>行动（A）</strong>：</p><ul><li><p>分析现有系统架构和性能瓶颈，与团队确定重构方案</p></li><li><p>设计 RESTful API 端点，定义清晰的输入输出模型</p></li><li><p>使用 Spring Boot + Hibernate + JPA 实现 API 开发</p></li><li><p>编写单元测试和集成测试保障代码质量</p></li><li><p>与前端紧密协作，输出 API 文档并通过代码审查推进协作</p></li></ul><p><strong>结果（R）</strong>：</p><ul><li><p>按时交付，响应时间缩短 40%，超出预期</p></li><li><p>代码可维护性显著提升，获得前端团队好评</p></li></ul></blockquote><p><strong>小技巧</strong>：把每段项目经历套进这个模板梳理一遍，原本说不清楚的经历，往往会变得极其清晰。做项目时就可以提前按这个框架做记录，方便后期写简历。</p><hr><h1 id="三段式法则" tabindex="-1">三段式法则 <a class="header-anchor" href="#三段式法则" aria-label="Permalink to &quot;三段式法则&quot;">​</a></h1><p>STAR 法则信息量大，但结构稍复杂。如果面对的是<strong>非技术背景的面试官</strong>（国企里这类人不少），推荐用更简洁的三段式。</p><p>三段式和 STAR 本质相同，都完成了<strong>发现问题 → 解决问题 → 取得成果</strong>的闭环，但读起来更直白。</p><h2 id="三段结构" tabindex="-1">三段结构 <a class="header-anchor" href="#三段结构" aria-label="Permalink to &quot;三段结构&quot;">​</a></h2><p><strong>① 项目背景</strong></p><p>简洁说明项目来源和你的角色。重点突出能让项目&quot;显分量&quot;的背景信息：实验室背景、公司背景、行业规模等。</p><p><strong>② 工作内容</strong></p><p>描述你解决问题的过程，技术类经历要写清楚用到的具体技术点。</p><p><strong>③ 工作成果</strong></p><p>最重要的部分。整段经历的闭环，必须有产出——数据、交付物、效果，能量化尽量量化。</p><h3 id="示例-1" tabindex="-1">示例 <a class="header-anchor" href="#示例-1" aria-label="Permalink to &quot;示例&quot;">​</a></h3><blockquote><p><strong>项目背景</strong>：xxxx 年，参与公司订单管理系统重构项目，负责设计和实现 RESTful API 接口，处理复杂订单查询逻辑，对接前端应用。</p><p><strong>工作内容</strong>：</p><ul><li><p>分析现有系统瓶颈，与团队制定重构方案</p></li><li><p>设计 API 端点及输入输出模型，使用 Spring Boot + JPA 完成开发</p></li><li><p>编写自动化测试用例，输出 API 文档，与前端团队协作完成联调</p></li></ul><p><strong>工作成果</strong>：</p><ul><li><p>按时交付，接口响应时间缩短 40%</p></li><li><p>代码可维护性提升，通过全部自动化测试</p></li></ul></blockquote><hr><h1 id="两种方法怎么选" tabindex="-1">两种方法怎么选？ <a class="header-anchor" href="#两种方法怎么选" aria-label="Permalink to &quot;两种方法怎么选？&quot;">​</a></h1><table tabindex="0"><thead><tr><th>场景</th><th>推荐</th></tr></thead><tbody><tr><td>技术岗位、年轻面试官、互联网背景公司</td><td>STAR 法则</td></tr><tr><td>央国企、传统行业、年龄偏大的面试官</td><td>三段式法则</td></tr><tr><td>简历空间有限</td><td>三段式法则（更简洁）</td></tr><tr><td>面试现场口头介绍</td><td>STAR 法则（结构感更强）</td></tr></tbody></table><p>两种方法可以结合用：<strong>简历上用三段式，面试现场口述用 STAR</strong>，效果最好。</p>',28)])])}const c=r(e,[["render",l]]);export{g as __pageData,c as default};
